static exr_result_t
silent_error (
    const struct _internal_exr_context* pctxt,
    exr_result_t                        code,
    const char*                         msg)
{
    (void)pctxt;
    (void)msg;
    return code;
}

static exr_result_t
silent_standard_error (
    const struct _internal_exr_context* pctxt, exr_result_t code)
{
    (void)pctxt;
    return code;
}

static exr_result_t
silent_print_error (
    const struct _internal_exr_context* pctxt,
    exr_result_t                        code,
    const char*                         msg,
    ...)
{
    (void)pctxt;
    (void)msg;
    return code;
}

